import re
from dataclasses import dataclass, field
from typing import Optional

# "## [2.4.0] - 2024-05-02" or "## [Unreleased]" (no date).
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# An HTML comment, possibly spanning several lines.
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)

# Spaces between a removed comment and the end of its line.
TRAILING_SPACE = re.compile(r"[ \t]*(?=\n|\Z)")


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def _strip_comments(text):
    """Remove HTML comments, dropping whitespace a comment leaves at line end."""
    pieces = []
    last = 0
    for match in COMMENT.finditer(text):
        before = text[last:match.start()]
        end = match.end()
        trailing = TRAILING_SPACE.match(text, end)
        if trailing:
            before = before.rstrip(" \t")
            end = trailing.end()
        pieces.append(before)
        last = end
    pieces.append(text[last:])
    return "".join(pieces)


def parse_changelog(text):
    releases = []
    current = None
    # Comments go first so that a heading-like line inside a comment is ignored.
    for line in _strip_comments(text.replace("\r\n", "\n")).split("\n"):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                raise ValueError(f"malformed release heading: {line!r}")
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _tidy_body(lines):
    """Blank out whitespace-only lines, collapse blank runs, trim the ends."""
    out = []
    for line in lines:
        if line.strip() == "":
            line = ""
            if out and out[-1] == "":
                continue
        out.append(line)
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            heading = f"# {release.version}"
            if release.date:
                heading += f" ({release.date})"
            body = _tidy_body(release.body)
            return f"{heading}\n\n{body}\n" if body else f"{heading}\n"
    raise LookupError(version)

